//
// Option pricing on grids: an American binomial tree with early exercise, and an explicit
// finite-difference solver for the Black-Scholes PDE. Both work on whole arrays per time
// step, using slices of the previous step's values.
#pragma once

#include <cmath>
#include <stdexcept>
#include "qtrans_arrays.hpp"  // Eigen, plus NumPy semantics

namespace lattice_pde {

// Declarations (so functions can call each other in any order).
double american_binomial(double S0, double K, double r, double sigma, double T, long long steps, bool is_call = false);
double early_exercise_premium(double S0, double K, double r, double sigma, double T, long long steps);
qt::Vec bs_explicit_fd(double K, double r, double sigma, double T, double S_max, long long n_s, long long n_t, bool is_call = true);
double fd_price(double S0, double K, double r, double sigma, double T, double S_max, long long n_s, long long n_t, bool is_call = true);

/// Cox-Ross-Rubinstein tree; at each node the holder takes the larger of continuation
/// and immediate exercise.
inline double american_binomial(double S0, double K, double r, double sigma, double T, long long steps, bool is_call) {
    if (steps < 1) {
        throw std::invalid_argument("steps must be at least 1");
    }
    double dt = T / static_cast<double>(steps);
    double u = std::exp(sigma * std::sqrt(dt));
    double d = 1.0 / u;
    double p = (std::exp(r * dt) - d) / (u - d);
    if (!(0 < p && p < 1)) {
        // outside (0, 1) the tree admits arbitrage and values grow like p^steps: refuse
        throw std::invalid_argument("risk-neutral probability outside (0, 1): use more steps");
    }
    double disc = std::exp(-r * dt);
    qt::Vec j = qt::arange(static_cast<double>(steps + 1));
    qt::Vec S = S0 * qt::pow(u, j) * qt::pow(d, static_cast<double>(steps) - j);  // terminal stock prices, lowest first
    qt::Vec V = is_call ? qt::Vec(qt::maximum(S - K, 0.0)) : qt::Vec(qt::maximum(K - S, 0.0));
    for (long long _ = 0; _ < steps; ++_) {
        S = (qt::slice(S, qt::none, -1) / d).eval();  // one step back: node j had price S_j(n) / d
        qt::Vec cont = disc * (p * qt::slice(V, 1, qt::none) + (1 - p) * qt::slice(V, qt::none, -1));
        qt::Vec exercise = is_call ? qt::Vec(S - K) : qt::Vec(K - S);
        V = qt::maximum(cont, exercise);
    }
    return V(0);
}

/// American minus European put on the same tree.
inline double early_exercise_premium(double S0, double K, double r, double sigma, double T, long long steps) {
    double dt = T / static_cast<double>(steps);
    double u = std::exp(sigma * std::sqrt(dt));
    double d = 1.0 / u;
    double p = (std::exp(r * dt) - d) / (u - d);
    if (!(0 < p && p < 1)) {
        throw std::invalid_argument("risk-neutral probability outside (0, 1): use more steps");
    }
    double disc = std::exp(-r * dt);
    qt::Vec j = qt::arange(static_cast<double>(steps + 1));
    qt::Vec V = qt::maximum(K - S0 * qt::pow(u, j) * qt::pow(d, static_cast<double>(steps) - j), 0.0);
    for (long long _ = 0; _ < steps; ++_) {
        V = (disc * (p * qt::slice(V, 1, qt::none) + (1 - p) * qt::slice(V, qt::none, -1))).eval();
    }
    return american_binomial(S0, K, r, sigma, T, steps) - V(0);
}

/// European option values at t = 0 on the grid S_i = i * S_max / n_s, by explicit
/// finite differences backwards from the payoff. Stable when dt < 1 / (sigma^2 n_s^2).
inline qt::Vec bs_explicit_fd(double K, double r, double sigma, double T, double S_max, long long n_s, long long n_t, bool is_call) {
    double dt = T / static_cast<double>(n_t);
    qt::Vec S = qt::linspace(0.0, S_max, n_s + 1);
    qt::Vec V = is_call ? qt::Vec(qt::maximum(S - K, 0.0)) : qt::Vec(qt::maximum(K - S, 0.0));
    qt::Vec i = qt::arange(1.0, static_cast<double>(n_s));
    qt::Vec a = 0.5 * dt * (sigma * sigma * i.square() - r * i);
    qt::Vec b = 1.0 - dt * (sigma * sigma * i.square() + r);
    qt::Vec c = 0.5 * dt * (sigma * sigma * i.square() + r * i);
    for (long long k = 1; k < n_t + 1; ++k) {
        double tau = static_cast<double>(k) * dt;
        qt::slice(V, 1, -1) = (a * qt::slice(V, qt::none, -2) + b * qt::slice(V, 1, -1) + c * qt::slice(V, 2, qt::none)).eval();  // every interior node from the old values
        if (is_call) {
            V(0) = 0.0;
            V(V.size() - 1) = S_max - K * std::exp(-r * tau);
        } else {
            V(0) = K * std::exp(-r * tau);
            V(V.size() - 1) = 0.0;
        }
    }
    return V;
}

/// Price at S0, interpolating linearly between grid nodes.
inline double fd_price(double S0, double K, double r, double sigma, double T, double S_max, long long n_s, long long n_t, bool is_call) {
    qt::Vec V = bs_explicit_fd(K, r, sigma, T, S_max, n_s, n_t, is_call);
    double dS = S_max / static_cast<double>(n_s);
    long long i = qt::to_int(qt::floordiv(S0, dS));
    if (i < 0 || i >= n_s) {
        throw std::invalid_argument("S0 must lie inside the grid");
    }
    double w = (S0 - static_cast<double>(i) * dS) / dS;
    return (1 - w) * V(qt::idx(i, V.size())) + w * V(qt::idx(i + 1, V.size()));
}

}  // namespace lattice_pde
